import { createContext, useContext } from "react";
import { WorkshopType } from "@/components/form/workshop/schema";

export const WorkshopOptionsContext = createContext<{
  workshop: WorkshopType;
} | null>(null);

export const useWorkshopOptionsContext = () => {
  const ctx = useContext(WorkshopOptionsContext);
  if (!ctx)
    throw new Error(
      "useWorkshopOptionsContext must be used within WorkshopOptionsContext.Provider",
    );
  return ctx;
};
