import { getModuleValues } from "../dataFunctions";
import { withForm } from "@/hooks/formContext";
import { useSelector } from "@tanstack/react-form";
import { workshopEmpty } from "./schema";

export const ModulesToggleForm = withForm({
  defaultValues: workshopEmpty,
  render: function Render({ form }) {
    const system = useSelector(
      form.store,
      (state) => state.values.user_options.system,
    );
    const option = useSelector(
      form.store,
      (state) => state.values.user_options.option,
    );
    const systems = system ? [system] : [];
    const options = option ? [option] : [];
    const communityModules = Object.fromEntries(
      getModuleValues(
        options,
        systems,
        "JupyterLab",
        "communities",
        "communitySet",
      ).map((mod) => [mod.id, mod.displayname]),
    );
    const extensionModules = Object.fromEntries(
      getModuleValues(
        options,
        systems,
        "JupyterLab",
        "extensions",
        "extensionSet",
      ).map((mod) => [mod.id, mod.displayname]),
    );
    const kernelModules = Object.fromEntries(
      getModuleValues(
        options,
        systems,
        "JupyterLab",
        "kernels",
        "kernelSet",
      ).map((mod) => [mod.id, mod.displayname]),
    );
    const proxyModules = Object.fromEntries(
      getModuleValues(
        options,
        systems,
        "JupyterLab",
        "proxies",
        "proxySet",
      ).map((mod) => [mod.id, mod.displayname]),
    );
    return (
      <>
        <form.AppField name="user_options.modules.communities">
          {(field) => (
            <field.toggle
              label="Communities"
              options={communityModules}
              hasCheckbox={true}
            />
          )}
        </form.AppField>
        <form.AppField name="user_options.modules.extensions">
          {(field) => (
            <field.toggle
              label="Extensions"
              options={extensionModules}
              hasCheckbox={true}
            />
          )}
        </form.AppField>
        <form.AppField name="user_options.modules.kernels">
          {(field) => (
            <field.toggle
              label="Kernels"
              options={kernelModules}
              hasCheckbox={true}
            />
          )}
        </form.AppField>
        <form.AppField name="user_options.modules.proxies">
          {(field) => (
            <field.toggle
              label="Proxies"
              options={proxyModules}
              hasCheckbox={true}
            />
          )}
        </form.AppField>
      </>
    );
  },
});
