import { useState } from "react";
import { Collapsible } from "radix-ui";
import { useAppForm, SubmitAction } from "@/hooks/formContext";
import { buildHumanReadableQuery } from "@/utils/APIUtils";
import { ChevronDownIcon, PlusIcon } from "@radix-ui/react-icons";
import { RowContext } from "@/hooks/RowContext";
import { workshopSchema } from "./schema";
import { WorkshopForm } from "./WorkshopForm";
import "./workshop.css";
import { useWorkshopOptionsContext } from "./workshopOptionsContext";
import Button from "@/components/Button/Button";

const defaultSubmitAction: SubmitAction = { submitAction: null };

interface WorkshopRowProps {
  isFirst?: boolean;
}

const WorkshopRow = ({ isFirst = false }: WorkshopRowProps) => {
  const [isRowOpen, setIsRowOpen] = useState(false);
  const workshop = useWorkshopOptionsContext().workshop;

  const form = useAppForm({
    defaultValues: workshop,
    onSubmitMeta: defaultSubmitAction,
    onSubmit: ({ value, meta }) => {
      switch (meta.submitAction) {
        case "url":
          console.log("Generated URL Query: ", buildHumanReadableQuery(value));
          break;
        case "reset":
          form.reset();
          break;
        case "submit":
          console.log("Form submitted with values: ", value);
          break;
        default:
          break;
      }
    },
    validators: {
      onChange: workshopSchema,
    },
  });
  return (
    <RowContext.Provider
      value={{
        isRowOpen,
        openRow: () => setIsRowOpen(true),
        closeRow: () => setIsRowOpen(false),
      }}
    >
      <Collapsible.Root asChild open={isRowOpen} onOpenChange={setIsRowOpen}>
        <tbody className="jh-table__body">
          <Collapsible.Trigger asChild>
            <tr className="jh-row workshop-row__trigger">
              <td className="workshop-row__toggle-cell">
                {isFirst ? (
                  <PlusIcon className="jh-chevron" />
                ) : (
                  <ChevronDownIcon className="jh-chevron" />
                )}
              </td>
              {isFirst && (
                <>
                  <td colSpan={1} className="workshop-row__label-cell">
                    <span className="workshop-row__title">New Workshop</span>
                  </td>
                  <td colSpan={5} className="workshop-row__label-cell">
                    <span className="workshop-row__title">
                      Design a simplified set of options for your workshop to
                      make it more accessible for your students.
                    </span>
                  </td>
                  <td className="workshop-row__action-cell">
                    <Button
                      type="button"
                      onClick={(event) => {
                        event.stopPropagation();
                        setIsRowOpen(true);
                      }}
                    >
                      Create
                    </Button>
                  </td>
                </>
              )}
              {!isFirst && (
                <>
                  <td colSpan={1} className="workshop-row__label-cell">
                    <span className="workshop-row__title">
                      {workshop.workshop_id}
                    </span>
                  </td>
                  <td colSpan={5} className="workshop-row__label-cell">
                    <span className="workshop-row__title">
                      {workshop.user_options.description}
                    </span>
                  </td>
                  <td className="workshop-row__action-cell"></td>
                </>
              )}
            </tr>
          </Collapsible.Trigger>
          <Collapsible.Content asChild>
            <tr className="workshop-row__content-row">
              <td
                colSpan={8}
                className="jh-content-cell workshop-row__content-cell"
              >
                <WorkshopForm form={form} />
              </td>
            </tr>
          </Collapsible.Content>
        </tbody>
      </Collapsible.Root>
    </RowContext.Provider>
  );
};

export default WorkshopRow;
