import { StrictMode } from "react";
import LogoutDialog from "./components/LogoutDialog/LogoutDialog";
import { WorkshopContext } from "./hooks/WorkshopContext";
import { createRoot } from "react-dom/client";
import WorkshopRow from "./components/form/workshop/WorkshopRow";
import { WorkshopOptionsContext } from "./components/form/workshop/workshopOptionsContext";
import { workshopEmpty, WorkshopType } from "./components/form/workshop/schema";
import "./style/table.css";
import "./style/main.css";

interface WorkshopTableProps {
  workshops: Record<string, WorkshopType>;
}

const WorkshopTable = ({ workshops }: WorkshopTableProps) => {
  return (
    <table className="jh-table">
      <colgroup>
        <col style={{ width: "40px" }} />
        <col style={{ width: "15%" }} />
        <col style={{ width: "15%" }} />
        <col style={{ width: "15%" }} />
        <col style={{ width: "15%" }} />
        <col style={{ width: "15%" }} />
        <col style={{ width: "15%" }} />
        <col style={{ width: "120px" }} />
        {/* Action */}
      </colgroup>
      <thead className="jh-thead">
        <tr>
          <th></th>
          <th>Name</th>
          <th colSpan={5}>Description</th>
          <th>Action</th>
        </tr>
      </thead>
      <WorkshopOptionsContext.Provider value={{ workshop: workshopEmpty }}>
        <WorkshopRow isFirst />
      </WorkshopOptionsContext.Provider>
      {Object.entries(workshops || {})
        .filter(([workshopID]) => workshopID !== "")
        .map(([workshopID, workshop]) => (
          <WorkshopOptionsContext.Provider
            key={workshopID}
            value={{ workshop: workshop }}
          >
            <WorkshopRow />
          </WorkshopOptionsContext.Provider>
        ))}
    </table>
  );
};

const WorkshopApp = () => {
  const workshopOptions = window.getWorkshopOptions();
  return (
    <StrictMode>
      <WorkshopContext.Provider value={{ test: "test" }}>
        <main className="home-container">
          <WorkshopTable workshops={workshopOptions} />
        </main>
      </WorkshopContext.Provider>
      <LogoutDialog />
    </StrictMode>
  );
};

const container = document.getElementById("react-workshop-hook");
const root = createRoot(container!);
root.render(<WorkshopApp />);
