import { withForm } from "@/hooks/formContext";
import { workshopEmpty, workshopSchema } from "./schema";
import { getSystemType } from "../shared/systemHelper";
import "./workshop.css";
import {
  homeTriggerFlavor,
  homeTriggerOption,
  homeTriggerPartition,
  homeTriggerProject,
  homeTriggerSystem,
} from "../dataFunctions";
import { useState } from "react";
import Button from "@/components/Button/Button";
import { ModulesToggleForm } from "./ModulesFormToggle";
import { fillMappingDict } from "@/utils/sharedHelper";

interface Option {
  options: Record<string, string>;
  inactiveOptions?: Record<string, string>;
  inactiveText?: string;
  groups?: Record<string, number>;
  multiple?: boolean;
  emptyOpt?: string;
}

export const WorkshopForm = withForm({
  defaultValues: workshopEmpty,
  validators: {
    onChange: workshopSchema,
  },
  render: function Render({ form }) {
    const mappingdict = fillMappingDict();
    const [optionOptions] = useState<Option>(homeTriggerOption());
    const [systemOptions, setSystemOptions] = useState<Option>(
      homeTriggerSystem(
        form.getFieldValue("user_options.option"),
        "jupyterlab",
      ),
    );
    const [projectOptions, setProjectOptions] = useState<Option>(
      homeTriggerProject(
        form.getFieldValue("user_options.system"),
        "",
        "configId",
        "jupyterlab",
      ),
    );

    console.log("Project options:", projectOptions);
    const [partitionOptions, setPartitionOptions] = useState<Option>({
      options: {},
    });
    const [flavorOptions, setFlavorOptions] = useState<Option>(
      homeTriggerFlavor(form.state.values.user_options.system),
    );

    console.log("Partition options:", partitionOptions);

    const handleSubmit = () => {
      const values = form.state.values;
      console.log("Workshop form values:", values);

      const parsed = workshopSchema.safeParse(values);

      if (!parsed.success) {
        console.error("Workshop form parse errors:", parsed.error.flatten());
        return;
      }
      console.log("Parsed workshop values:", parsed.data);
    };

    return (
      <form
        className="workshop-form"
        onSubmit={(event) => {
          event.preventDefault();
          handleSubmit();
        }}
      >
        <div className="workshop-form__body">
          <div className="workshop-form__column">
            <div className="workshop-form__field">
              <form.AppField name="workshop_id">
                {(field) => <field.text label="Workshop ID" />}
              </form.AppField>
            </div>
            <div className="workshop-form__field">
              <form.AppField name="user_options.description">
                {(field) => <field.text label="Description" />}
              </form.AppField>
            </div>
            <div className="workshop-form__field">
              <form.AppField name="user_options.userlist">
                {(field) => (
                  <field.text
                    type="textarea"
                    label="Restrict workshop access to specific users"
                    hasCheckbox={true}
                  />
                )}
              </form.AppField>
            </div>
            <div className="workshop-form__field">
              <form.Subscribe
                selector={(state) => state.values.user_options.userlist}
              >
                <form.AppField name="user_options.tutorlist">
                  {(field) => (
                    <field.text
                      type="textarea"
                      label="Add workshop tutors"
                      hasCheckbox={true}
                    />
                  )}
                </form.AppField>
                <form.Subscribe
                  selector={(state) => state.values.user_options.tutorlist}
                >
                  <form.AppField name="user_options.workshop_tutor_server_access">
                    {(field) => (
                      <field.checkbox label="Allow tutors to access participant servers (cloud only)" />
                    )}
                  </form.AppField>
                </form.Subscribe>
                <form.AppField name="user_options.workshop_storage_rw">
                  {(field) => (
                    <field.checkbox label="Allow participants to write to shared storage" />
                  )}
                </form.AppField>
                <p>Request additional credits for this workshop</p>
              </form.Subscribe>
            </div>
          </div>

          <div className="workshop-form__column">
            <div className="workshop-form__field">
              <form.AppField name="user_options.option">
                {(field) => (
                  <field.select
                    label="Select version"
                    options={optionOptions}
                    hasCheckbox={true}
                  />
                )}
              </form.AppField>
            </div>
            <div className="workshop-form__field">
              <form.AppField
                name="user_options.system"
                validators={{
                  onChangeListenTo: ["user_options.option"],
                  onChange: ({ value, fieldApi }) => {
                    const option = fieldApi.form.getFieldValue(
                      "user_options.option",
                    );
                    const service = fieldApi.form.getFieldValue(
                      "user_options.service",
                    );
                    const options = homeTriggerSystem(option, service);
                    if (
                      options.inactiveOptions &&
                      options.inactiveOptions[value]
                    ) {
                      console.warn(
                        `Selected value "${value}" is in inactive options. Resetting selection.`,
                      );
                      const firstOption = Object.keys(options.options)[0];
                      if (firstOption) {
                        fieldApi.handleChange(firstOption);
                      }
                    }
                    setSystemOptions(options ?? []);
                  },
                }}
              >
                {(field) => (
                  <field.select
                    label="System"
                    options={systemOptions}
                    hasCheckbox={true}
                  />
                )}
              </form.AppField>
            </div>
            <form.Subscribe
              selector={(state) => state.values.user_options.option}
            >
              {(option) => (
                <div>
                  {mappingdict["jupyterlab"].option[option] == "lmod" && (
                    <div className="workshop-form__field">
                      <ModulesToggleForm form={form} />
                    </div>
                  )}
                </div>
              )}
            </form.Subscribe>
            <form.Subscribe
              selector={(state) => state.values.user_options.system}
            >
              {(system) =>
                getSystemType(system) === "hpc" && (
                  <>
                    <div className="workshop-form__field">
                      <form.AppField
                        name="user_options.hpc.project"
                        listeners={{
                          onMount: ({ fieldApi }) => {
                            const system = fieldApi.form.getFieldValue(
                              "user_options.system",
                            );
                            const options = homeTriggerProject(
                              system,
                              "",
                              "configId",
                              "jupyterlab",
                            );
                            setProjectOptions(options ?? []);
                          },
                        }}
                      >
                        {(field) => (
                          <field.toggle
                            label="Project"
                            options={projectOptions.options}
                            hasCheckbox={true}
                          />
                        )}
                      </form.AppField>
                    </div>
                    <form.Subscribe
                      selector={(state) =>
                        state.values.user_options.hpc.project
                      }
                    >
                      {(project) =>
                        project && project.length > 1 ? (
                          <div>
                            <form.AppField name="user_options.defaultvalues.project">
                              {(field) => (
                                <field.select
                                  label="Prefered project"
                                  options={projectOptions}
                                />
                              )}
                            </form.AppField>
                          </div>
                        ) : null
                      }
                    </form.Subscribe>
                    <div className="workshop-form__field">
                      <form.AppField
                        name="user_options.hpc.partition"
                        validators={{
                          onChangeListenTo: [
                            "user_options.hpc.project",
                            "user_options.system",
                          ], // homeTriggerPartition
                          onChange: ({ fieldApi }) => {
                            const project =
                              fieldApi.form.getFieldValue(
                                "user_options.hpc.project",
                              ) || "_all_";
                            const system = fieldApi.form.getFieldValue(
                              "user_options.system",
                            );
                            const options = homeTriggerPartition(
                              system,
                              "_all_",
                              project,
                              "configId",
                              "jupyterlab",
                            );
                            setPartitionOptions(options ?? []);
                          },
                        }}
                        listeners={{
                          onMount: ({ fieldApi }) => {
                            const project =
                              fieldApi.form.getFieldValue(
                                "user_options.hpc.project",
                              ) || "_all_";
                            const system = fieldApi.form.getFieldValue(
                              "user_options.system",
                            );
                            const options = homeTriggerPartition(
                              system,
                              "_all_",
                              project,
                              "configId",
                              "jupyterlab",
                            );
                            setPartitionOptions(options ?? []);
                          },
                        }}
                      >
                        {(field) => (
                          <field.toggle
                            label="Partition"
                            options={partitionOptions.options}
                            hasCheckbox={true}
                          />
                        )}
                      </form.AppField>
                    </div>
                    <form.Subscribe
                      selector={(state) =>
                        state.values.user_options.hpc.partition
                      }
                    >
                      {(partitions) =>
                        partitions && partitions.length > 1 ? (
                          <div>
                            <form.AppField name="user_options.defaultvalues.partition">
                              {(field) => (
                                <field.select
                                  label="Prefered Partition"
                                  options={partitionOptions}
                                  hasCheckbox={true}
                                />
                              )}
                            </form.AppField>
                          </div>
                        ) : null
                      }
                    </form.Subscribe>
                    <div className="workshop-form__field">
                      <form.AppField name="user_options.hpc.reservation">
                        {(field) => (
                          <field.text label="Reservation" hasCheckbox={true} />
                        )}
                      </form.AppField>
                    </div>
                    <div className="workshop-form__field">
                      <form.AppField name="user_options.resources.nodes">
                        {(field) => (
                          <field.text label="Nodes [x, X]" hasCheckbox={true} />
                        )}
                      </form.AppField>
                    </div>
                    <div className="workshop-form__field">
                      <form.AppField name="user_options.resources.runtime">
                        {(field) => (
                          <field.text
                            label="Runtime [x, X]"
                            hasCheckbox={true}
                          />
                        )}
                      </form.AppField>
                    </div>
                    <div className="workshop-form__field">
                      <form.AppField name="user_options.resources.gpus">
                        {(field) => (
                          <field.text label="GPUs [x, X]" hasCheckbox={true} />
                        )}
                      </form.AppField>
                    </div>
                    <div className="workshop-form__field">
                      <form.AppField name="user_options.resources.xserver">
                        {(field) => (
                          <field.text label="X Server" hasCheckbox={true} />
                        )}
                      </form.AppField>
                    </div>
                  </>
                )
              }
            </form.Subscribe>
            <form.Subscribe
              selector={(state) =>
                state.values.user_options.option === "repo2docker"
              }
            >
              {(isRepo2Docker) =>
                isRepo2Docker && (
                  <>
                    <div className="workshop-form__field">
                      <form.AppField name="user_options.repo2docker.repotype">
                        {(field) => (
                          <field.text
                            label="Repository Type"
                            hasCheckbox={true}
                          />
                        )}
                      </form.AppField>
                    </div>

                    <div className="workshop-form__field">
                      <form.AppField name="user_options.repo2docker.repourl">
                        {(field) => (
                          <field.text
                            label="GitHub repository name or URL"
                            hasCheckbox={true}
                          />
                        )}
                      </form.AppField>
                    </div>

                    <div className="workshop-form__field">
                      <form.AppField name="user_options.repo2docker.reporef">
                        {(field) => (
                          <field.text
                            label="Git ref (branch, tag or commit)"
                            hasCheckbox={true}
                          />
                        )}
                      </form.AppField>
                    </div>

                    <div className="workshop-form__field">
                      <form.AppField name="user_options.repo2docker.repopath">
                        {(field) => (
                          <field.text
                            label="Open notebook or path (optional)"
                            hasCheckbox={true}
                          />
                        )}
                      </form.AppField>
                    </div>

                    <div className="workshop-form__field">
                      <form.AppField name="user_options.repo2docker.repopathtype">
                        {(field) => (
                          <field.text
                            label="Notebook Type"
                            hasCheckbox={true}
                          />
                        )}
                      </form.AppField>
                    </div>
                  </>
                )
              }
            </form.Subscribe>

            <form.Subscribe
              selector={(state) => state.values.user_options.option == "custom"}
            >
              {(isCustom) =>
                isCustom && (
                  <>
                    <div className="workshop-form__field">
                      <form.AppField name="user_options.custom.customimage">
                        {(field) => (
                          <field.text label="Image" hasCheckbox={true} />
                        )}
                      </form.AppField>
                    </div>
                    <div className="workshop-form__field">
                      <form.AppField name="user_options.custom.privaterepo">
                        {(field) => (
                          <field.text
                            label="Private image repository"
                            hasCheckbox={true}
                          />
                        )}
                      </form.AppField>
                    </div>
                    <div className="workshop-form__field">
                      <form.AppField name="user_options.custom.privaterepousername">
                        {(field) => (
                          <field.text label="Username" hasCheckbox={true} />
                        )}
                      </form.AppField>
                    </div>
                  </>
                )
              }
            </form.Subscribe>

            <form.Subscribe
              selector={(state) =>
                state.values.user_options.option == "custom" ||
                state.values.user_options.option == "repo2docker"
              }
            >
              {(isR2DOrCustom) =>
                isR2DOrCustom && (
                  <div className="workshop-form__field">
                    <form.AppField name="user_options.storage.localstoragepath">
                      {(field) => (
                        <field.text
                          label="Mount user data"
                          hasCheckbox={true}
                        />
                      )}
                    </form.AppField>
                  </div>
                )
              }
            </form.Subscribe>

            <div className="workshop-form__field">
              <form.AppField name="user_options.envvariables">
                {(field) => (
                  <field.envAdder
                    label="Environment variables"
                    hasCheckbox={true}
                  />
                )}
              </form.AppField>
            </div>
            <form.Subscribe
              selector={(state) => state.values.user_options.system}
            >
              {(system) =>
                getSystemType(system) === "cloud" && (
                  <div className="workshop-form__field">
                    <form.AppField
                      name="user_options.flavor"
                      validators={{
                        onChangeListenTo: ["user_options.system"],
                        onChange: ({ value, fieldApi }) => {
                          const system = fieldApi.form.getFieldValue(
                            "user_options.system",
                          );
                          const options = homeTriggerFlavor(system);
                          if (
                            value == "" &&
                            options.options &&
                            Object.keys(options.options).length > 0
                          ) {
                            const firstOption = Object.keys(options.options)[0];
                            fieldApi.handleChange(firstOption);
                          }
                          setFlavorOptions(options ?? []);
                        },
                      }}
                    >
                      {(field) => (
                        <field.select
                          label="Flavor"
                          options={flavorOptions}
                          hasCheckbox={true}
                        />
                      )}
                    </form.AppField>
                  </div>
                )
              }
            </form.Subscribe>
          </div>
          <form.AppForm>
            <Button type="submit" className="workshop-form__submit-button">
              Submit
            </Button>
          </form.AppForm>
        </div>
      </form>
    );
  },
});
