import {
  getBackendServices,
  getSystemConfig,
} from "@/utils/frontendCollectionHelper";

const getSystemType = (system: string | string[] | undefined) => {
  const systemConfig = getSystemConfig();
  const backendServicesConfig = getBackendServices();
  if (!system) {
    return "none";
  }
  if (Array.isArray(system)) {
    for (const sys of system) {
      const backendService = systemConfig[sys]?.backendService;
      if (!backendService) {
        console.warn("No backend service found for system:", sys);
        continue; // Skip to the next system if no backend service is found
      }
      const ret = backendServicesConfig[backendService]?.mapping ?? sys;
    }
    return "cloud";
  } else {
    const backendService = systemConfig[system]?.backendService;
    console.log("Backend service for system", system, ":", backendService);
    if (!backendService) {
      console.warn("No backend service found for system:", system);
      return "cloud"; // Default to cloud if no backend service is found
    }
    const ret = backendServicesConfig[backendService]?.mapping ?? system;
    return ret == "unicore" ? "hpc" : "cloud";
  }
};

export { getSystemType };
