import * as z from "zod";
import {
  repo2dockerSchema,
  baseCustomSchema,
  baseHpcSchema,
  resourcesSchema,
  modulesSchema,
  envVariableSchema,
} from "../shared/schema";

const hpcSchema = baseHpcSchema.extend({
  partition: z.optional(z.array(z.string().trim())),
  project: z.optional(z.array(z.string().trim())),
  reservation: z.optional(z.array(z.string().trim())),
});

export const workshopSchema = z.object({
  workshop_id: z.string().trim(),
  instructor_user_id: z.int(),
  user_options: z.object({
    description: z.string().trim(),
    expertmode: z.boolean(),
    name: z.string().trim(),
    workshop_storage_rw: z.boolean(),
    workshop_tutor_server_access: z.boolean(),
    workshopid: z.string().trim(),
    secret_keys: z.array(z.string().trim()),
    profile: z.string().trim(),
    option: z.optional(z.string().trim()),
    system: z.optional(z.string().trim()),
    service: z.string().trim(),
    userlist: z.optional(z.string().trim()),
    tutorlist: z.optional(z.string().trim()),
    defaultvalues: z.optional(z.record(z.string().trim(), z.string().trim())),
    resources: resourcesSchema,
    envvariables: z.optional(z.array(envVariableSchema)),
    hpc: z.optional(hpcSchema),
    modules: z.optional(modulesSchema),
    repo2docker: z.optional(repo2dockerSchema),
    custom: z.optional(baseCustomSchema),
    storage: z.optional(
      z.object({
        localstoragepath: z
          .optional(z.string().trim())
          .prefault("/home/jovyan/work"),
      }),
    ),
    flavor: z.optional(z.string().trim()),
  }),
});

export type WorkshopType = z.infer<typeof workshopSchema>;

